ValidationRule.errorConditionFormula:
AND(
    NOT(
        OR(
            $Profile.Name = "System Administrator",
            $Profile.Name = "Utkarsh Admin"
        )
    ),

    ISCHANGED(Description),

    OR(
        /* Condition 1: User is not the Owner */
        OwnerId <> $User.Id,

        /* Condition 2: Record is Resolved */
        ISPICKVAL(Status, "Resolved")
    )
)
